import { z } from "zod";

/** Database IDs are cuid-style strings generated by Prisma. */
export const idSchema = z
  .string()
  .trim()
  .min(1)
  .max(64)
  .regex(/^[a-z0-9]+$/i, "Invalid identifier");

export const paginationSchema = z.object({
  cursor: idSchema.optional(),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type Pagination = z.infer<typeof paginationSchema>;

/** Free-text user instructions (e.g. "Format my resume using Client A template"). */
export const userInstructionSchema = z.string().trim().min(1).max(4000);
